{
  "root_causes": [
    {
      "service": "shipping",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "log", "sql": "SELECT time, service_name, message FROM abnormal_logs WHERE service_name='shipping' AND message LIKE 'SIGTERM%' ORDER BY time", "claim": "Shipping logged 'SIGTERM received; starting graceful shutdown' at 03:49:50, followed by 'accept thread stopped' and idle worker shutdown."},
        {"kind": "trace", "sql": "SELECT (SELECT count(*) FROM normal_traces WHERE service_name='shipping') AS spans_normal, (SELECT count(*) FROM abnormal_traces WHERE service_name='shipping') AS spans_abnormal", "claim": "Shipping emitted spans in the normal window but none at all in the abnormal window after its shutdown."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='checkout' AND span_name='HTTP POST' GROUP BY ALL", "claim": "Checkout's outbound HTTP POST calls to shipping all end in Error with no child spans, i.e. the callee is gone."}
      ]
    },
    {
      "service": "frontend",
      "fault_kind": "dns_lookup_failed",
      "evidence": [
        {"kind": "trace", "sql": "SELECT time, service_name, span_name, attr_status_code, duration FROM abnormal_traces WHERE span_name='dns.lookup' ORDER BY time", "claim": "Frontend dns.lookup spans fail with Error status in the abnormal window, and none of them succeed."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) n, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE 'grpc.oteldemo.ProductReviewService%' GROUP BY ALL", "claim": "Frontend's ProductReviewService gRPC calls all fail in about 0.3-0.5 ms with no child spans, consistent with a name lookup failure."},
        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE 'GET /api/product-reviews%' GROUP BY ALL", "claim": "Frontend's product-reviews HTTP route returns 500 for every request in the abnormal window."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "shipping",
      "to": "checkout",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE span_name IN ('oteldemo.CheckoutService/PlaceOrder','HTTP POST') GROUP BY ALL", "claim": "Checkout HTTP POST to shipping and checkout PlaceOrder both end in Error in the abnormal window."}
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE span_name IN ('grpc.oteldemo.CheckoutService/PlaceOrder','POST /api/checkout') GROUP BY ALL", "claim": "Frontend's PlaceOrder client calls and POST /api/checkout return errors and HTTP 500 when checkout fails."}
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' AND attr_http_response_status_code=500 GROUP BY ALL", "claim": "Frontend-proxy ingress returns HTTP 500 on requests that failed inside frontend, reaching users."}
      ]
    }
  ]
}

